import SwiftUI
import Foundation

/// The six P3 map styles (App/Resources/MapStyle, generated by tools/stylegen from design/p3v3).
enum MapStyleKind: String, CaseIterable, Sendable {
    case standard, outdoor, satellite

    init(_ style: MapStyleSheet.Style) {
        switch style {
        case .standard: self = .standard
        case .outdoor: self = .outdoor
        case .satellite: self = .satellite
        }
    }
}

enum MapMode: String, CaseIterable, Sendable {
    case day, night

    /// The map's light or dark style: the phone's appearance unless the rider picked one (Map sheet, 30 Oct).
    init(_ scheme: ColorScheme, _ appearance: MapAppearance) {
        switch appearance {
        case .auto: self = scheme == .dark ? .night : .day
        case .light: self = .day
        case .dark: self = .night
        }
    }
}

/// Map sheet → Light / Dark / Auto (follows the phone).
enum MapAppearance: String, CaseIterable, Codable, Sendable {
    case auto, light, dark
    var title: String { switch self { case .auto: "Auto"; case .light: "Light"; case .dark: "Dark" } }
}

private struct MapAppearanceKey: EnvironmentKey { static let defaultValue = MapAppearance.auto }
extension EnvironmentValues {
    /// Set at the root from ``AppState/mapAppearance``; every map reads it.
    var mapAppearance: MapAppearance {
        get { self[MapAppearanceKey.self] }
        set { self[MapAppearanceKey.self] = newValue }
    }
}

enum VelixMapStyle {
    enum Failure: Error { case missingStyle(String) }

    /// OpenFreeMap's OpenMapTiles TileJSON, used only until the pack's basemap is installed.
    static let onlineBasemap = "https://tiles.openfreemap.org/planet"

    /// The bundled style JSON with its `pmtiles://velix-pack/` sources pointed at the pack's files, written to Caches.
    /// Glyphs load from the bundle (`asset://MapStyle/glyphs`); images come from ``MapImages``.
    static func url(_ kind: MapStyleKind, _ mode: MapMode, basemap: URL? = RegionPack.basemap,
                    overlays: URL? = RegionPack.overlays) throws -> URL {
        let name = "\(kind.rawValue)-\(mode.rawValue)"
        guard let src = Bundle.main.url(forResource: name, withExtension: "json", subdirectory: "MapStyle") else {
            throw Failure.missingStyle(name)
        }
        var json = try String(contentsOf: src, encoding: .utf8)
        // No pack yet (first launch, S0e: "explore the map" while it downloads): the same OpenMapTiles schema online.
        json = json.replacingOccurrences(of: "pmtiles://velix-pack/basemap.pmtiles",
                                         with: basemap.map { "pmtiles://\($0.absoluteString)" } ?? onlineBasemap)
        if let overlays {
            json = json.replacingOccurrences(of: "pmtiles://velix-pack/overlays.pmtiles", with: "pmtiles://\(overlays.absoluteString)")
        }
        let dir = URL.cachesDirectory.appending(path: "MapStyle", directoryHint: .isDirectory)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let out = dir.appending(path: "\(name).json")
        try json.write(to: out, atomically: true, encoding: .utf8)
        return out
    }

    /// Layers the MapStyleSheet overlay toggles switch (on / off variants share an id prefix).
    static func visibility(bikeLanes: Bool, transitLines: Bool, layerIDs: [String]) -> [String: Bool] {
        var out: [String: Bool] = [:]
        for id in layerIDs {
            if id.hasPrefix("overlay-cycle-") || id.hasPrefix("eurovelo-") { out[id] = bikeLanes }
            else if id.hasPrefix("overlay-train") || id.hasPrefix("overlay-metro") || id == "overlay-station-metro" { out[id] = transitLines }
            else if id == "station-metro" { out[id] = !transitLines }
        }
        return out
    }
}
